Vrtc vrtc_build( Vrtc_Func func , UInt16 size  )
{    
	Vrtc vrtc ;  

	vrtc_init() ;
	
	vrtc = (Vrtc)os_mem_request( size ) ;
	
	if( vrtc )
	{ 	
		vrtc->timeout   = 0         ; 
	
		vrtc->is_enable = FALSE     ; 
	
		vrtc->func      = func      ;

		reg_func_arg( vrtc_table , 0 , (Reg_Func)vrtc_exec , (Reg_Own_Arg)vrtc );
	}
	
	return vrtc ; 
}

